#nullable enable // autogenerated

using System;
using PVZEngine.Entities;
using PVZEngine.Level;

namespace PVZEngine.Damages
{
    public class DeathInfo
    {
        public DamageEffectList Effects { get; private set; }
        public Entity Entity { get; private set; }
        public ILevelSourceReference? Source { get; set; }
        public DamageResultValues? Damage { get; private set; }

        public DeathInfo(Entity entity, DamageEffectList effects, ILevelSourceReference? source, DamageResultValues? damage = null)
        {
            Effects = effects;
            Entity = entity;
            Source = source;
            Damage = damage;
        }
        public DeathInfo(LevelEngine level, SerializableDeathInfo seri)
        {
            var ent = level.FindEntityByID(seri.entityID);
            if (ent == null)
            {
                throw new NullReferenceException($"Cannot find the entity with id {seri.entityID} while loading SerializableDeathInfo.");
            }
            Entity = ent;
            Effects = new DamageEffectList(seri.effects);
            Source = seri.source?.ToDeserialized(level);
            Damage = seri.damage;
        }
        public bool HasEffect(NamespaceID effect)
        {
            if (Effects == null)
                return false;
            return Effects.HasEffect(effect);
        }
    }
    [Serializable]
    public class SerializableDeathInfo
    {
        public NamespaceID[] effects;
        public long entityID;
        public ISerializableSourceReference? source;
        public DamageResultValues? damage;

        public SerializableDeathInfo(DeathInfo deathInfo)
        {
            effects = deathInfo.Effects.GetEffects();
            damage = deathInfo.Damage;
            source = deathInfo.Source?.ToSerializable();
            entityID = deathInfo.Entity.ID;
        }
    }
}
